#!/usr/bin/env python3

import sys
import math
from collections import defaultdict


def LI():
    return list(map(int, sys.stdin.buffer.readline().split()))


def I():
    return int(sys.stdin.buffer.readline())


def LS():
    return sys.stdin.buffer.readline().rstrip().decode('utf-8').split()


def S():
    return sys.stdin.buffer.readline().rstrip().decode('utf-8')


def IR(n):
    return [I() for i in range(n)]


def LIR(n):
    return [LI() for i in range(n)]


def SR(n):
    return [S() for i in range(n)]


def LSR(n):
    return [LS() for i in range(n)]


def SRL(n):
    return [list(S()) for i in range(n)]


def MSRL(n):
    return [[int(j) for j in list(S())] for i in range(n)]

# ----------------------------------------------------------------

def prime_factorization(N):
    A=list(range(2,N+1))
    p=[]
    while A[0]**2<=N:
        tmp=A[0]
        p.append(tmp)
        A=[e for e in A if e%tmp!=0]
    return(p+A)



def main():
    N = I()
    if N == 1:
        print(1)
        exit()

    prime = prime_factorization(N)
    mod = 10**9 + 7

    d = defaultdict(lambda: 1)


    for i in range(1,N+1):
        for p in prime:
            if i>=p:
                while i%p == 0:
                    d[p] += 1
                    i /= p
            else:
                break

    ans = 1

    for k in d.values():
        ans *= k

    print(ans%mod)

