class UnionFind:
    def __init__(self, n):
        self.par = [-1] * n

    def root(self, x):
        if self.par[x] < 0:
            return x
        else:
            self.par[x] = self.root(self.par[x])
            return self.par[x]

    def unite(self, x, y):
        x, y = self.root(x), self.root(y)

        if x == y:
            return

        if self.par[x] > self.par[y]:
            x, y = y, x

        self.par[x] += self.par[y]
        self.par[y] = x

    def same(self, x, y):
        return self.root(x) == self.root(y)


def solve(N, XY):
    for i in range(N):
        XY[i].append(i)

    edge = []

    L = sorted(XY, key=lambda x: x[0])
    for i in range(N - 1):
        l1 = L[i]
        l2 = L[i + 1]
        dx = abs(l1[0] - l2[0])
        dy = abs(l1[1] - l2[1])

        if dx <= dy:
            edge.append((l1[2], l2[2], dx))
        else:
            edge.append((l1[2], l2[2], dy))

    L = sorted(XY, key=lambda x: x[1])
    for i in range(N - 1):
        l1 = L[i]
        l2 = L[i + 1]
        dx = abs(l1[0] - l2[0])
        dy = abs(l1[1] - l2[1])

        if dx <= dy:
            edge.append((l1[2], l2[2], dx))
        else:
            edge.append((l1[2], l2[2], dy))

    edge.sort(key=lambda x: x[2])
    ans = 0
    uf = UnionFind(N)

    for x, y, w in edge:
        if uf.same(x, y):
            continue

        uf.unite(x, y)
        ans += w

    return ans


